// SpecNames lists every spec name, sorted by file name.
func SpecNames() []string {
	return []string{"dist-dashboard.json", "dist-dev.json", "dist-hello.json", "dist-simple-cli.json", "dist.json"}
}

// Loader installs the graph named by a spec. An unknown name **errors**; it does not
// fall back to the default -- "I built the simple one, why does the UI show two"
// deserves an answer in the first second of startup, not a manual binary diff.
type Loader struct{ Spec string }

// PrecomputedOrder hands over the start order the distribution computed at build time.
//
// With it, the runtime does not build a port table, build dependency edges, topo-sort
// or look for cycles -- all that happened at build time (tools/distgen runs a real
// Resolve; see order_gen.go). A manifest that disagrees with the selection errors on
// the spot instead of staying quiet.
func (l Loader) PrecomputedOrder() []string {
	name := l.Spec
	if name == "" {
		name = DefaultSpec
	}
	return startOrder[name]
}

func (l Loader) Load() ([]modules.Component, error) {
	name := l.Spec
	if name == "" {
		name = DefaultSpec
	}
	sel, ok := Specs()[name]
	if !ok {
		return nil, fmt.Errorf("no spec named %q (available: %s)", name, strings.Join(SpecNames(), ", "))
	}
	return sel.Load()
}
